// Parse Claude response and create delivery package
const claudeResponse = JSON.parse($input.item.json.content[0].text);
const orderData = $('Filter New Orders').item.json;

return {
  json: {
    order_id: orderData.order_id,
    buyer_username: orderData.buyer_username,
    package_type: orderData.package,
    gig_title: orderData.gig_title,
    analysis: claudeResponse,
    delivery_date: new Date().toISOString(),
    status: 'processed'
  }
};

